import random

def play_game():
    secret = random.randint(1, 100)
    attempts = 0
    won = False
    print('Game starts!')

    while attempts < 7:
        guess = int(input('Guess: '))
        attempts += 1
        if guess < secret:
            print('Too low')
        elif guess > secret:
            print('Too high')
        else:
            won = True
            break

    if won:
        print(f'You got it in {attempts} guesses!')
    else:
        print(f'Game over! The number was {secret}.')

while True:
    play_game()
    again = input('Play again? (y/n): ')
    if again.lower() != 'y':
        break

